//! Disposable benchmark of existing numeric Bytes operations.
#[path = "../tests/support/oop.rs"]
mod oop;
use birnam_abi::{size, Oop};
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let h = oop::bootstrap();
    let q = h.scope();
    let integer = h.named(b"Integer").unwrap();
    let gc = h.named(b"GC").unwrap();
    let bytes = q.call(h.named(b"Bytes").unwrap(), b"fromByteValues",
        &[1,2,3,4,0,0,0,0].map(|v| size(v).unwrap())).unwrap();
    let zero = q.call(integer, b"fromWord:", &[size(0).unwrap()]).unwrap();
    let eight = q.call(integer, b"fromWord:", &[size(8).unwrap()]).unwrap();
    q.call(gc, b"automaticCollection:", &[size(0).unwrap()]).unwrap();
    let cases: &[(&[u8], &[Oop], usize)] = &[
        (b"size", &[], 8), (b"at:", &[zero], 1),
        (b"readU32At:", &[zero], 0x04030201),
        (b"readU64At:", &[zero], 0x04030201),
        (b"copyFrom:to:", &[zero, eight], 8),
    ];
    for &(name, args, expected) in cases {
        let selector = q.keep(h.intern(name).unwrap()).unwrap();
        for _ in 0..100 { unsafe { h.id.send(bytes, selector, args).unwrap(); } }
        for _ in 0..7 {
            q.call(gc, b"collectPrecisely", &[]).unwrap();
            let mut last = bytes;
            let start = unsafe { clock_gettime_nsec_np(16) };
            for _ in 0..20000 { last = unsafe { h.id.send(bytes, selector, args).unwrap() }; }
            let elapsed = unsafe { clock_gettime_nsec_np(16) } - start;
            if name == b"copyFrom:to:" {
                assert_eq!(unsafe { h.id.send(last, h.intern(b"sizeWord").unwrap(), &[]).unwrap() }, size(expected as usize).unwrap());
            } else {
                let word = unsafe { h.id.send(integer, h.intern(b"wordOf:").unwrap(), &[last]).unwrap() };
                assert_eq!(q.word_bits(word).unwrap(), expected);
            }
            println!("{} {elapsed}", String::from_utf8_lossy(name));
        }
    }
}
